    policy = ProcessPolicy(config.CORE_PROCESS_WAIT_INTERVAL_SECONDS, config.CORE_CLIENT_SHUTDOWN_TIMEOUT_SECONDS, config.CORE_PROCESS_JOB_SNAPSHOT_ATTEMPTS)
